export const WatchActivityWindowSchema = z.enum(["24h","yesterday","7d","30d"]).describe("Bounded time windows for the action-activity summary, selected by a\nclient and resolved to concrete `(since, until)` bounds SERVER-side (one\nsource of truth, server clock). Applied by run EVALUATION time\n(`completed_at`). No unbounded 'all' value: a count is always over a\nfinite range. Default is `WEEK`.");
export type WatchActivityWindow = z.infer<typeof WatchActivityWindowSchema>;

export const WatchWireSchema = z.object({ "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "feed_ids": z.array(z.string()).optional(), "id": z.string(), "is_active": z.boolean(), "name": z.string(), "user_id": z.string() }).describe("The envelope every `/v1/watches` response item carries. List-item\nshape and base for the detail / mutation responses.\n\n`feed_ids` is the watch's subscription set (the WatchFeed rows,\nminus the internal per-feed watermark which never crosses the wire).\nDatetimes are real `datetime` (None pre-save); JSON encoding is the\nrenderer's job. `user_id` is creator/audit only (account-scoped\nreads, not an ownership filter).");
export type WatchWire = z.infer<typeof WatchWireSchema>;

export const WebhookMethodSchema = z.enum(["POST","PUT","PATCH"]).describe("HTTP verb a webhook action delivers with. Body-bearing verbs only:\nGET (no body) is deferred (it would map item fields to query params, a\nseparate shape). PUT / PATCH are idempotent, which pairs with the\ndelivery dedup.");
export type WebhookMethod = z.infer<typeof WebhookMethodSchema>;

export const WebhookResultSchema = z.object({ "http_status": z.number().int() }).describe("Result a webhook run writes to WatchActionRun.result: the HTTP status\nof the call that SUCCEEDED (a 2xx ; a non-2xx raises and the run is\nFAILED instead).");
export type WebhookResult = z.infer<typeof WebhookResultSchema>;

export const WebhookRunWireSchema = z.object({ "action_id": z.string(), "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "error": z.string().default(""), "feed_item_id": z.string(), "id": z.string(), "kind": z.literal("webhook").default("webhook"), "result": z.union([WebhookResultSchema, z.null()]).default(null), "scheduled_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionRunStateSchema, "watch_id": z.string() });
export type WebhookRunWire = z.infer<typeof WebhookRunWireSchema>;

export const BackfillJobSchema = z.object({ "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "completed_since": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "completed_until": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "deleted": z.number().int().default(0), "enqueued": z.number().int().default(0), "error": z.string().default(""), "id": z.string(), "kind": z.union([WatchActionKindSchema, z.string()]).default(""), "matched": z.number().int().default(0), "occurred_since": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "occurred_until": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "present": z.number().int().default(0), "pruned": z.number().int().default(0), "replace": z.boolean().default(false), "source_action_id": z.string().default(""), "source_is_head": z.boolean().default(false), "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionBackfillStateSchema, "target_action_id": z.string() }).describe("A queued backfill's definition + progress.\n\nThe counts are 0 until `process_due_backfills` runs the job, then reflect what\nit actually did: `matched` source passes in the window, `present`/`pruned`\nsplit, `deleted` terminal runs removed (target + downstream, when `replace`),\n`enqueued` fresh target runs created. `source_action_id` is empty for a\nchain-head target (see `BackfillPreview`).\n\n`kind` is the target action's kind (a `WatchActionKind`; `| str` tolerates a\nsince-removed kind, mirroring the run wire). The four window bounds are the\nresolved absolute datetimes (None = unbounded on that side). `error` carries the\nreason when `state` is FAILED; a FAILED job is retryable while `completed_at` is\nunset and terminal once it's set (the attempts cap was hit), mirroring a run.");
export type BackfillJob = z.infer<typeof BackfillJobSchema>;

export const BackfillListResponseSchema = z.object({ "items": z.array(BackfillJobSchema).optional(), "next_cursor": z.union([z.string(), z.null()]).default(null) }).describe("`GET /v1/action-backfills` envelope: this account's backfill jobs, newest-first.\n`next_cursor` is the id to pass as `?after=` for the next page (None at the\nend).");
export type BackfillListResponse = z.infer<typeof BackfillListResponseSchema>;

export const EngineListResponseSchema = z.object({ "items": z.array(EngineStatusSchema).default([]) }).describe("`GET /v1/engines` envelope. One entry per registered engine kind.");
export type EngineListResponse = z.infer<typeof EngineListResponseSchema>;

export const ExtractConfigSchema = z.object({ "engine": EngineSpecSchema.optional(), "fetch_external_content": z.boolean().default(true), "fields": z.array(ExtractFieldSchema).max(64), "instructions": z.string().max(2048).default("") }).describe("Config for a WatchAction with kind == 'extract'.\n\nHydration only: the engine reads each item (optionally with its fetched\nlinked-article text) and returns a value for every declared `field`,\npersisted under `result.extracted`. No threshold, no gate ; the run\nalways SUCCEEDS so the chain advances. Domain-agnostic ; the field set\nand `instructions` are entirely operator-supplied.");
export type ExtractConfig = z.infer<typeof ExtractConfigSchema>;

export const ExtractResultSchema = z.object({ "enrichment_status": ExternalContentStatusSchema, "extracted": z.record(z.string(), z.string()).optional(), "status": ExtractStatusSchema }).describe("Result an extract run writes to WatchActionRun.result.\n\n`extracted` is the `{field name: value}` map (string values in v1 ; the\nreport renders them as cells and projects `result.extracted.<name>`).\n`status` is how complete the extraction was: COMPLETE (every declared field\nfilled), PARTIAL (some), EMPTY (none). The action always sets it explicitly ;\nthe EMPTY default just covers a result built without one. `enrichment_status`\nrecords how the linked-article fetch fared (the article TEXT is never stored ;\nthe fetch is lazy + ephemeral).");
export type ExtractResult = z.infer<typeof ExtractResultSchema>;

export const ExtractRunWireSchema = z.object({ "action_id": z.string(), "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "error": z.string().default(""), "feed_item_id": z.string(), "id": z.string(), "kind": z.literal("extract").default("extract"), "result": z.union([ExtractResultSchema, z.null()]).default(null), "scheduled_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionRunStateSchema, "watch_id": z.string() });
export type ExtractRunWire = z.infer<typeof ExtractRunWireSchema>;

export const FeedInputSchema = z.object({ "data": CuratedFeedConfigSchema.optional(), "is_active": z.boolean().default(true), "kind": z.string().default("curated"), "name": z.string(), "poll_interval_seconds": z.number().int().default(300), "sources": z.array(SourceInputSchema).optional() }).describe("The envelope the CLI constructs for a feed write (request side). CLI-owned,\ndistinct from the server-emitted models (mirrors WatchInput). `data` carries\nthe kind-specific config (retention + default_field_map), opaque here; the\nserver validates it. `sources` is the optional starter source list for curated\nfeeds (the server creates Source rows atomically with the Feed). Extra keys\nignored so an edit seed's read-only fields drop on round-trip.");
export type FeedInput = z.infer<typeof FeedInputSchema>;

export const FeedItemWireSchema = z.object({ "data": z.union([RssEntryPayloadSchema, NewRedditPostPayloadSchema, HackerNewsFeedPayloadSchema, HackerNewsCommentPayloadSchema, FeedItemPayloadSchema]).optional(), "external_id": z.string(), "id": z.string(), "occurred_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "source_kind": z.string(), "source_label": z.string().default("") }).describe("One persisted FeedItem on the wire ; the \"sort by new and go\" unit.\n\n`data` is the connector SourcePayload's dump, parsed into a typed\n`FeedItemData` (canonical fields typed for every kind; connector-specific\nfields typed per known kind; unknown kinds fall to the permissive base).\nDatetimes stay real; the renderer ISO-encodes them.\n\n`source_kind` is the connector kind (e.g. `\"reddit_subreddit\"`),\ndenormalized from the producing Source. `source_label` is the\noperator-visible display string (e.g. `\"r/ClaudeCowork\"`), set on\nthe FeedItem row at record time from the SourceSpec's `.display()`.");
export type FeedItemWire = z.infer<typeof FeedItemWireSchema>;

export const FeedListResponseSchema = z.object({ "items": z.array(FeedWireSchema).optional(), "next_cursor": z.union([z.string(), z.null()]).default(null) }).describe("`GET /v1/feeds` -> `{\"items\": [...], \"next_cursor\": <id>|None}`.\n\nCursor-paginated by ULID pk, newest-first. Pass `?after=<id>` to fetch\nthe next page; `next_cursor` is the id to send back, or null when the\npage wasn't full (= no more rows).");
export type FeedListResponse = z.infer<typeof FeedListResponseSchema>;

export const FeedMutationResponseSchema = z.object({ "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "data": CuratedFeedConfigSchema.optional(), "dry_run": z.boolean(), "id": z.union([z.string(), z.null()]).default(null), "is_active": z.boolean(), "kind": z.string(), "last_polled_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "name": z.string(), "next_poll_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "poll_interval_seconds": z.number().int(), "source_count": z.number().int().default(0), "sources": z.array(SourceWireSchema).optional(), "summary": FeedConfigSummarySchema.optional(), "user_id": z.string() }).describe("Create / edit response (POST + PUT, real and `?dry_run=true`).\n`id` absent on a create dry-run preview; `dry_run` True for preview.\nCarries the same `sources` + `source_count` enrichment as FeedView\nso the CLI's confirm-preview shows the operator the post-mutation\nsource list without an extra GET.");
export type FeedMutationResponse = z.infer<typeof FeedMutationResponseSchema>;

export const FeedViewSchema = z.object({ "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "data": CuratedFeedConfigSchema.optional(), "id": z.string(), "is_active": z.boolean(), "kind": z.string(), "last_polled_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "name": z.string(), "next_poll_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "poll_interval_seconds": z.number().int(), "source_count": z.number().int().default(0), "sources": z.array(SourceWireSchema).optional(), "summary": FeedConfigSummarySchema.optional(), "user_id": z.string() }).describe("`GET /v1/feeds/<id>` - the feed's CONFIG detail: the kind-independent\nenvelope + display `summary` + its currently-attached Source rows. The item\nlog is NOT carried here; it has its own paginated route\n(`GET /v1/feeds/<id>/items`, the `feed item list` reader).");
export type FeedView = z.infer<typeof FeedViewSchema>;

export const LogActionInputSchema = z.object({ "config": LogConfigSchema, "id": z.string().default(""), "kind": z.literal("log").default("log"), "rank": z.union([z.number().int(), z.null()]).default(null) });
export type LogActionInput = z.infer<typeof LogActionInputSchema>;

export const LogActionWireSchema = z.object({ "config": z.union([LogConfigSchema, z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "id": z.string().default(""), "kind": z.literal("log").default("log"), "rank": z.number().int(), "summary": WatchActionConfigSummarySchema.optional() });
export type LogActionWire = z.infer<typeof LogActionWireSchema>;

export const LogRunWireSchema = z.object({ "action_id": z.string(), "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "error": z.string().default(""), "feed_item_id": z.string(), "id": z.string(), "kind": z.literal("log").default("log"), "result": z.union([LogResultSchema, z.null()]).default(null), "scheduled_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionRunStateSchema, "watch_id": z.string() });
export type LogRunWire = z.infer<typeof LogRunWireSchema>;

export const PluginActionInputSchema = z.object({ "config": PluginConfigBlobSchema, "id": z.string().default(""), "kind": z.string().min(1).max(32), "rank": z.union([z.number().int(), z.null()]).default(null) }).describe("Fallback input member for a plugin (non-built-in) action kind. Mirrors\nPluginActionWire on the write path; `config` is required (you can't author an\naction without one) but open (validated server-side by the kind's registry).");
export type PluginActionInput = z.infer<typeof PluginActionInputSchema>;

export const PluginActionWireSchema = z.object({ "config": z.union([z.record(z.string(), z.any()), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "id": z.string().default(""), "kind": z.string().min(1).max(32), "rank": z.number().int(), "summary": WatchActionConfigSummarySchema.optional() }).describe("Fallback wire member for a plugin (non-built-in) action kind. `kind` is any\nnon-built-in string; `config` is an untyped blob (a fork's typed config schema\nlives in the fork's own contract, and its web/CLI narrow on `kind`). Selected\nonly when no built-in discriminator matches (see the left-to-right union).");
export type PluginActionWire = z.infer<typeof PluginActionWireSchema>;

export const PluginRunWireSchema = z.object({ "action_id": z.string(), "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "error": z.string().default(""), "feed_item_id": z.string(), "id": z.string(), "kind": z.string().min(1).max(32), "result": z.union([z.record(z.string(), z.any()), z.null()]).default(null), "scheduled_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionRunStateSchema, "watch_id": z.string() }).describe("Fallback run member for a plugin (non-built-in) action kind. `result` is an\nuntyped blob (a fork's typed result schema lives in its own contract). Selected\nonly when no built-in discriminator matches (left-to-right union).");
export type PluginRunWire = z.infer<typeof PluginRunWireSchema>;

export const SemanticFilterActionInputSchema = z.object({ "config": SemanticFilterConfigSchema, "id": z.string().default(""), "kind": z.literal("semantic_filter").default("semantic_filter"), "rank": z.union([z.number().int(), z.null()]).default(null) });
export type SemanticFilterActionInput = z.infer<typeof SemanticFilterActionInputSchema>;

export const SemanticFilterActionWireSchema = z.object({ "config": z.union([SemanticFilterConfigSchema, z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "id": z.string().default(""), "kind": z.literal("semantic_filter").default("semantic_filter"), "rank": z.number().int(), "summary": WatchActionConfigSummarySchema.optional() });
export type SemanticFilterActionWire = z.infer<typeof SemanticFilterActionWireSchema>;

export const SemanticFilterRunWireSchema = z.object({ "action_id": z.string(), "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "error": z.string().default(""), "feed_item_id": z.string(), "id": z.string(), "kind": z.literal("semantic_filter").default("semantic_filter"), "result": z.union([SemanticFilterResultSchema, z.null()]).default(null), "scheduled_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionRunStateSchema, "watch_id": z.string() });
export type SemanticFilterRunWire = z.infer<typeof SemanticFilterRunWireSchema>;

export const WatchActionDeliveryViewSchema = z.object({ "action_id": z.string(), "attempt": z.number().int().default(0), "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "delivery": DeliveryCadenceSchema, "error": z.string().default(""), "http_status": z.union([z.number().int(), z.null()]).default(null), "id": z.string(), "item_count": z.number().int().default(0), "method": WebhookMethodSchema, "request_payload": z.record(z.string(), z.any()).optional(), "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionDeliveryStateSchema, "target_host": z.string().default(""), "watch_id": z.string() }).describe("`GET /v1/action-deliveries/<delivery_id>`, the detail: the list row plus the\nexact `request_payload` we sent (a WebhookPayload dump), stored\npoint-in-time. Opaque here ; headers are NEVER included (auth tokens). Kept\noff the list wire so a list call doesn't ship every batch body.");
export type WatchActionDeliveryView = z.infer<typeof WatchActionDeliveryViewSchema>;

export const WatchActionDeliveryWireSchema = z.object({ "action_id": z.string(), "attempt": z.number().int().default(0), "completed_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "delivery": DeliveryCadenceSchema, "error": z.string().default(""), "http_status": z.union([z.number().int(), z.null()]).default(null), "id": z.string(), "item_count": z.number().int().default(0), "method": WebhookMethodSchema, "started_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "state": WatchActionDeliveryStateSchema, "target_host": z.string().default(""), "watch_id": z.string() }).describe("One WatchActionDelivery on the LIST wire\n(`GET /v1/actions/<action_id>/deliveries`).\n\nOne outbound HTTP call ATTEMPT (a digest that retries makes several, one\nrow each). `target_host` is the redacted destination host (never the full\nURL or any secret). `http_status` is null until the call returns. The full\n`request_payload` is NOT here (it can be a large batch body) ; fetch one\ndelivery's detail (WatchActionDeliveryView) for it. Datetimes real; renderer\nencodes.");
export type WatchActionDeliveryWire = z.infer<typeof WatchActionDeliveryWireSchema>;

export const WatchActionRunSummarySchema = z.object({ "evaluated": z.record(z.string(), z.number().int()).optional(), "pending": z.number().int().default(0), "retrying": z.number().int().default(0), "running": z.number().int().default(0), "since": z.iso.datetime({ offset: true }), "until": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "window": WatchActivityWindowSchema }).describe("Activity over an action's runs, so an operator sees \"what is this\naction doing?\" without scrolling the log.\n\n`evaluated` is the per-terminal-state breakdown of runs JUDGED within\n[since, until), windowed on completion (evaluation) time, not enqueue\ntime. `pending` / `running` / `retrying` are the CURRENT live backlog,\nNOT time-bound (those runs have no completion time yet), surfaced so the\nqueue stays visible. `window` is the requested preset ; `since` / `until`\nare the concrete bounds the server resolved it to.\n\nDISJOINT by `completed_at`: a FAILED run is counted in `evaluated[failed]`\niff it's terminal (attempts exhausted -> has a completion time) and in\n`retrying` iff it's not (still under the cap -> no completion time). So a\nconsumer can sum across buckets without double-counting.");
export type WatchActionRunSummary = z.infer<typeof WatchActionRunSummarySchema>;

export const WatchListResponseSchema = z.object({ "items": z.array(WatchWireSchema).optional(), "next_cursor": z.union([z.string(), z.null()]).default(null) }).describe("`GET /v1/watches` -> `{\"items\": [...], \"next_cursor\": <id>|None}`.\n\nCursor-paginated by ULID pk, newest-first. Pass `?after=<id>` for the\nnext page; `next_cursor` is the id to send back, or null when the\npage wasn't full (no more rows).");
export type WatchListResponse = z.infer<typeof WatchListResponseSchema>;

export const WebhookConfigSchema = z.object({ "delivery": DeliveryCadenceSchema, "digest_interval_seconds": z.number().int().gte(0).default(0), "headers": z.record(z.string(), z.string()).optional(), "include_fields": z.array(z.string()).optional(), "method": WebhookMethodSchema, "url": z.string() }).describe("Config for a WatchAction with kind == 'webhook'.\n\nSends the item to `url` via `method` (POST | PUT | PATCH) with `headers`\n(sent verbatim, so they carry any auth token). `include_fields` whitelists\nwhich item fields are sent (empty = all). `delivery` /\n`digest_interval_seconds` (from the base) pick instant vs batched delivery.\n\nSecret-bearing: `url` path/query and every header VALUE are masked by\n`redacted_dump` and carried forward by `merge_preserving` when the\noperator leaves them masked on an edit.");
export type WebhookConfig = z.infer<typeof WebhookConfigSchema>;

export const ExtractActionInputSchema = z.object({ "config": ExtractConfigSchema, "id": z.string().default(""), "kind": z.literal("extract").default("extract"), "rank": z.union([z.number().int(), z.null()]).default(null) });
export type ExtractActionInput = z.infer<typeof ExtractActionInputSchema>;

export const ExtractActionWireSchema = z.object({ "config": z.union([ExtractConfigSchema, z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "id": z.string().default(""), "kind": z.literal("extract").default("extract"), "rank": z.number().int(), "summary": WatchActionConfigSummarySchema.optional() });
export type ExtractActionWire = z.infer<typeof ExtractActionWireSchema>;

export const FeedItemListResponseSchema = z.object({ "items": z.array(FeedItemWireSchema).optional(), "next_cursor": z.union([z.string(), z.null()]).default(null) }).describe("`GET /v1/feeds/<id>/items` -> `{\"items\": [...], \"next_cursor\": <id>|None}`.\n\nCursor-paginated by ULID pk, newest-first. Pass `?after=<id>` to fetch the\nnext page; `next_cursor` is the id to send back, or null when the page wasn't\nfull (= no more rows).");
export type FeedItemListResponse = z.infer<typeof FeedItemListResponseSchema>;

export const WatchActionDeliveryListResponseSchema = z.object({ "items": z.array(WatchActionDeliveryWireSchema).optional(), "next_cursor": z.union([z.string(), z.null()]).default(null) }).describe("`GET /v1/actions/<action_id>/deliveries` envelope. Cursor-paginated by\nULID pk, newest-first. `?after=<id>` for the next page; `next_cursor` null\nwhen the page wasn't full. Filter by `?state=` (a WatchActionDeliveryState\nvalue).");
export type WatchActionDeliveryListResponse = z.infer<typeof WatchActionDeliveryListResponseSchema>;

export const WebhookActionInputSchema = z.object({ "config": WebhookConfigSchema, "id": z.string().default(""), "kind": z.literal("webhook").default("webhook"), "rank": z.union([z.number().int(), z.null()]).default(null) });
export type WebhookActionInput = z.infer<typeof WebhookActionInputSchema>;

export const WebhookActionWireSchema = z.object({ "config": z.union([WebhookConfigSchema, z.null()]).default(null), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "id": z.string().default(""), "kind": z.literal("webhook").default("webhook"), "rank": z.number().int(), "summary": WatchActionConfigSummarySchema.optional() });
export type WebhookActionWire = z.infer<typeof WebhookActionWireSchema>;

export const WatchActionMutationResponseSchema = z.object({ "action": z.union([z.discriminatedUnion("kind", [SemanticFilterActionWireSchema, ExtractActionWireSchema, LogActionWireSchema, WebhookActionWireSchema]), PluginActionWireSchema]), "dry_run": z.boolean() }).describe("Single-action add/edit response (POST `/actions` + PUT `/actions/<id>`,\nreal and `?dry_run=true`). `dry_run` is True for a validation-only preview;\n`action` is the typed action node (a discriminated union). On a dry-run the\naction isn't persisted, so `action.id` is \"\" (WatchActionWire can't be\nsubclassed to null the id, so the response nests the action rather than\nflattening it as the pre-union shape did).");
export type WatchActionMutationResponse = z.infer<typeof WatchActionMutationResponseSchema>;

export const WatchActionRunListResponseSchema = z.object({ "action": z.union([z.discriminatedUnion("kind", [SemanticFilterActionWireSchema, ExtractActionWireSchema, LogActionWireSchema, WebhookActionWireSchema]), PluginActionWireSchema, z.null()]).default(null), "feed_items": z.record(z.string(), RunFeedItemSchema).optional(), "feeds": z.record(z.string(), RunFeedSchema).optional(), "items": z.array(z.union([z.discriminatedUnion("kind", [SemanticFilterRunWireSchema, ExtractRunWireSchema, LogRunWireSchema, WebhookRunWireSchema]), PluginRunWireSchema])).optional(), "next_cursor": z.union([z.string(), z.null()]).default(null), "summary": z.union([WatchActionRunSummarySchema, z.null()]).default(null) }).describe("`GET /v1/actions/<action_id>/activity` envelope. Cursor-paginated by ULID\npk, newest-first. `?after=<id>` for the next page; `next_cursor` null\nwhen the page wasn't full. Filter by `?state=` (a WatchActionRunState\nvalue). `summary` (the full per-state breakdown) is present on the\nfirst page only (omitted when paging with `?after=`).");
export type WatchActionRunListResponse = z.infer<typeof WatchActionRunListResponseSchema>;

export const WatchActionRunViewSchema = z.object({ "action": z.union([z.discriminatedUnion("kind", [SemanticFilterActionWireSchema, ExtractActionWireSchema, LogActionWireSchema, WebhookActionWireSchema]), PluginActionWireSchema, z.null()]).default(null), "feed": z.union([RunFeedSchema, z.null()]).default(null), "feed_item": z.union([RunFeedItemSchema, z.null()]).default(null), "run": z.union([z.discriminatedUnion("kind", [SemanticFilterRunWireSchema, ExtractRunWireSchema, LogRunWireSchema, WebhookRunWireSchema]), PluginRunWireSchema]) }).describe("`GET /v1/action-activity/<id>`: one run (\"activity entry\") in full, with\nthe joined item / feed / action so a reader sees WHAT it judged and under\nWHICH action without a second call. `run` is NESTED (not inherited the way\nWatchActionDeliveryView extends its wire) because the item / feed / action are\npeer joins onto the run, not extra columns on it. The list returns the same\njoin as keyed side tables; the detail inlines the one item + feed it needs.\n`feed_item` / `feed` are null when the item has been pruned by retention (the\nrun still renders by `run.feed_item_id`); `action` is null only if it was\nremoved.");
export type WatchActionRunView = z.infer<typeof WatchActionRunViewSchema>;

export const WatchInputSchema = z.object({ "actions": z.array(z.union([z.discriminatedUnion("kind", [SemanticFilterActionInputSchema, ExtractActionInputSchema, LogActionInputSchema, WebhookActionInputSchema]), PluginActionInputSchema])).optional(), "feed_ids": z.array(z.string()).optional(), "is_active": z.boolean().default(true), "name": z.string() }).describe("The envelope the CLI constructs for a watch write (request side).\nCLI-owned, distinct from the server-emitted models. `feed_ids` is the\nsubscription set; `actions` is the initial path's ordered chain. The\nserver creates the Watch + its single WatchPath + WatchFeed rows\natomically. Extra keys ignored so an edit seed's read-only fields\ndrop on round-trip.");
export type WatchInput = z.infer<typeof WatchInputSchema>;

export const WatchMutationResponseSchema = z.object({ "actions": z.array(z.union([z.discriminatedUnion("kind", [SemanticFilterActionWireSchema, ExtractActionWireSchema, LogActionWireSchema, WebhookActionWireSchema]), PluginActionWireSchema])).optional(), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "dry_run": z.boolean(), "feed_ids": z.array(z.string()).optional(), "id": z.union([z.string(), z.null()]).default(null), "is_active": z.boolean(), "name": z.string(), "user_id": z.string() }).describe("Create / edit response (POST + PUT, real and `?dry_run=true`).\n`id` is absent on a create dry-run preview (server omits the pre-save\nplaceholder), hence `str | None`. `dry_run` is True for a\nvalidation-only preview. Carries the same `actions` enrichment as\nWatchView so the CLI's confirm-preview shows the resulting chain.");
export type WatchMutationResponse = z.infer<typeof WatchMutationResponseSchema>;

export const WatchViewSchema = z.object({ "actions": z.array(z.union([z.discriminatedUnion("kind", [SemanticFilterActionWireSchema, ExtractActionWireSchema, LogActionWireSchema, WebhookActionWireSchema]), PluginActionWireSchema])).optional(), "created_at": z.union([z.iso.datetime({ offset: true }), z.null()]).default(null), "feed_ids": z.array(z.string()).optional(), "id": z.string(), "is_active": z.boolean(), "name": z.string(), "user_id": z.string() }).describe("`GET /v1/watches/<id>`, the read view: the envelope plus the\nordered action chain of the watch's initial path. v1 has exactly one\npath, so `actions` is that path's actions by `rank` ; the path layer\nstays hidden on the wire until multi-path ships.");
